`timescale 1ns/1ps
module tb_pq_kpoly;
reg clk=0, rst_n=0; always #5 clk=~clk;
reg start=0; reg [4:0] op=0; reg [5:0] sa=0,sb=0,sc=0; reg g2sel=0; reg [31:0] bound=0;
wire busy, done, flag_or; wire [8:0] hint_cnt; wire [13:0] ra, wa; wire we; wire [31:0] wd, rq;
pq_pm pm(.clk(clk), .we(we), .wa(wa), .wd(wd), .ra(ra), .rq(rq));
pq_poly dut(clk,rst_n,start,op,sa,sb,sc,g2sel,bound,busy,done,flag_or,hint_cnt,ra,we,wa,wd,rq,1'b1);
integer fails=0, n=0, i, c0, cyc=0; always @(posedge clk) cyc<=cyc+1; reg seen=0; always @(posedge clk) if (done) seen<=1;
task setp(input [5:0] s, input [8191:0] v); begin for (i=0;i<256;i=i+1) pm.mem[s*256+i] = v[32*i +: 32]; end endtask
task chk(input [5:0] s, input [8191:0] v, input [255:0] nm); begin for (i=0;i<256;i=i+1) if (pm.mem[s*256+i] !== v[32*i +: 32]) begin
   if (fails < 10) $display("FAIL slot %0d idx %0d got %h exp %h", s, i, pm.mem[s*256+i], v[32*i +: 32]); fails=fails+1; end end endtask
task run(input [4:0] o, input [5:0] a, input [5:0] b, input [5:0] c, input [31:0] bd); begin
  seen=0; c0=cyc; @(negedge clk); op=o; sa=a; sb=b; sc=c; bound=bd; start=1; @(negedge clk); start=0; wait(seen); repeat(3) @(negedge clk); end endtask
initial begin #30 rst_n=1; #30;
  setp(1, 8192');
  run(0,1,0,0,0); $display("kntt: %0d clk", cyc-c0);
  chk(1, 8192', "kntt");
  n=n+1;
  setp(2, 8192');
  run(0,2,0,0,0); $display("kntt_small: %0d clk", cyc-c0);
  chk(2, 8192', "kntt_small");
  n=n+1;
  setp(3, 8192');
  run(1,3,0,0,0); $display("kintt: %0d clk", cyc-c0);
  chk(3, 8192', "kintt");
  n=n+1;
  setp(5, 8192');
  setp(6, 8192');
  setp(4, 8192');
  run(14,4,5,6,0); $display("kpmulm: %0d clk", cyc-c0);
  chk(4, 8192', "kpmulm");
  n=n+1;
  setp(5, 8192');
  setp(6, 8192');
  setp(7, 8192');
  run(15,7,5,6,0); $display("kpmuln: %0d clk", cyc-c0);
  chk(7, 8192', "kpmuln");
  n=n+1;
  setp(4, 8192');
  setp(7, 8192');
  run(17,10,4,7,0); $display("kpcomb: %0d clk", cyc-c0);
  chk(10, 8192', "kpcomb");
  n=n+1;
  setp(8, 8192');
  run(16,8,0,0,4294966955); $display("kpscl_tomont: %0d clk", cyc-c0);
  chk(8, 8192', "kpscl_tomont");
  n=n+1;
  setp(9, 8192');
  run(16,9,0,0,1353); $display("kpscl_canon: %0d clk", cyc-c0);
  chk(9, 8192', "kpscl_canon");
  n=n+1;
  setp(9, 8192');
  run(7,9,0,0,0); $display("kcaddq: %0d clk", cyc-c0);
  chk(9, 8192', "kcaddq");
  n=n+1;
  if (fails==0) $display("ALL PASS (%0d ops)", n); else $display("FAILED (%0d mismatches)", fails);
  $finish;
end
initial begin #800000000 $display("TIMEOUT"); $finish; end
endmodule
